import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Users, Clock, AlertTriangle, Building2, ShieldCheck, RefreshCw } from 'lucide-react';

export default function App() {
  const [crowd, setCrowd] = useState(null);
  const [darshan, setDarshan] = useState([]);
  const [hotels, setHotels] = useState([]);
  const [lastPing, setLastPing] = useState("");

  const fetchData = async () => {
    try {
      const [crowdRes, darshanRes, hotelRes] = await Promise.all([
        fetch('http://localhost:8000/api/realtime/crowd-feed').then(r => r.json()),
        fetch('http://localhost:8000/api/realtime/darshan-timings').then(r => r.json()),
        fetch('http://localhost:8000/api/realtime/hotels').then(r => r.json())
      ]);
      setCrowd(crowdRes);
      setDarshan(darshanRes);
      setHotels(hotelRes);
      setLastPing(new Date().toLocaleTimeString());
    } catch (err) {
      console.error("Fetch failure:", err);
    }
  };

  useEffect(() => {
    fetchData();
    const interval = setInterval(fetchData, 4000); // Polls every 4s for live updates
    return () => clearInterval(interval);
  }, []);

  const getBadgeColor = (status) => {
    if (status === 'CRITICAL' || status === 'HEAVY CROWD') return '#dc2626';
    if (status === 'HIGH') return '#ea580c';
    if (status === 'MODERATE') return '#ca8a04';
    return '#16a34a';
  };

  return (
    <div style={{ background: '#f8fafc', minHeight: '100vh', padding: '24px 16px', fontFamily: 'Inter, sans-serif' }}>
      <div style={{ maxWidth: '1000px', margin: '0 auto' }}>
        
        {/* Header */}
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '24px' }}>
          <div>
            <h1 style={{ margin: 0, fontSize: '28px', color: '#0f172a' }}>🚩 Rahbar (रहबर)</h1>
            <p style={{ margin: '4px 0 0', color: '#64748b' }}>Real-Time Pilgrim Assistance, Crowd Balancer & Anti-Surge Radar</p>
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '8px', fontSize: '13px', background: '#e2e8f0', padding: '6px 12px', borderRadius: '20px' }}>
            <RefreshCw size={14} className="spin" style={{ color: '#0284c7' }} />
            <span>Telemetry Live: {lastPing || 'Syncing...'}</span>
          </div>
        </div>

        {/* Live Crowd Card */}
        {crowd && (
          <motion.div
            initial={{ opacity: 0, y: 15 }}
            animate={{ opacity: 1, y: 0 }}
            style={{
              background: '#ffffff',
              borderRadius: '16px',
              padding: '24px',
              boxShadow: '0 4px 20px -2px rgba(0,0,0,0.06)',
              borderLeft: `8px solid ${getBadgeColor(crowd.status)}`,
              marginBottom: '28px'
            }}
          >
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', flexWrap: 'wrap', gap: '12px' }}>
              <div>
                <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                  <Users size={20} color={getBadgeColor(crowd.status)} />
                  <span style={{ fontWeight: 'bold', color: '#334155' }}>CCTV Headcount Telemetry: {crowd.zone}</span>
                </div>
                <h2 style={{ fontSize: '32px', margin: '12px 0 6px', color: '#0f172a' }}>
                  {crowd.live_count} Pilgrims Detected
                </h2>
                <div style={{ color: '#64748b', fontSize: '14px' }}>
                  Density: <strong>{crowd.capacity_percentage}%</strong> of safe corridor capacity
                </div>
              </div>

              <motion.div
                key={crowd.status}
                initial={{ scale: 0.9 }}
                animate={{ scale: 1 }}
                style={{
                  background: getBadgeColor(crowd.status),
                  color: 'white',
                  padding: '8px 16px',
                  borderRadius: '30px',
                  fontWeight: 'bold',
                  fontSize: '14px'
                }}
              >
                STATUS: {crowd.status}
              </motion.div>
            </div>

            {/* Dynamic Redirection Engine Banner */}
            {crowd.redirection.recommended && (
              <motion.div
                initial={{ opacity: 0, height: 0 }}
                animate={{ opacity: 1, height: 'auto' }}
                style={{ marginTop: '20px', background: '#fffbeb', border: '1px solid #fde68a', padding: '16px', borderRadius: '12px', display: 'flex', gap: '12px', alignItems: 'center' }}
              >
                <AlertTriangle color="#d97706" size={24} />
                <div>
                  <strong style={{ color: '#92400e' }}>Smart Crowd Redistribution:</strong>
                  <div style={{ color: '#b45309', fontSize: '14px' }}>
                    Main route is currently bottlenecked. Redirect to <strong>{crowd.redirection.target}</strong>. Estimated time saved: <strong>{crowd.redirection.time_saved}</strong>.
                  </div>
                </div>
              </motion.div>
            )}
          </motion.div>
        )}

        {/* 2-Column Responsive Grid for Darshan & Hotels */}
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(320px, 1fr))', gap: '24px' }}>
          
          {/* Darshan Queues */}
          <div style={{ background: '#ffffff', padding: '20px', borderRadius: '16px', boxShadow: '0 4px 15px rgba(0,0,0,0.04)' }}>
            <h3 style={{ margin: '0 0 16px', display: 'flex', alignItems: 'center', gap: '8px', color: '#1e293b' }}>
              <Clock size={18} color="#ea580c" />
              Live Darshan Waiting Times
            </h3>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
              <AnimatePresence>
                {darshan.map((slot, index) => (
                  <motion.div
                    key={index}
                    whileHover={{ scale: 1.02 }}
                    transition={{ type: "spring", stiffness: 300 }}
                    style={{ background: '#f8fafc', border: '1px solid #e2e8f0', borderRadius: '10px', padding: '14px' }}
                  >
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                      <strong style={{ color: '#334155' }}>{slot.temple}</strong>
                      <span style={{ fontSize: '12px', fontWeight: 'bold', color: getBadgeColor(slot.status) }}>
                        {slot.wait_mins}m wait
                      </span>
                    </div>
                    <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '12px', color: '#64748b', marginTop: '6px' }}>
                      <span>Slot: {slot.slot}</span>
                      <span>Flow: {slot.status}</span>
                    </div>
                  </motion.div>
                ))}
              </AnimatePresence>
            </div>
          </div>

          {/* Hotel & Dharamshala Fair Price Radar */}
          <div style={{ background: '#ffffff', padding: '20px', borderRadius: '16px', boxShadow: '0 4px 15px rgba(0,0,0,0.04)' }}>
            <h3 style={{ margin: '0 0 16px', display: 'flex', alignItems: 'center', gap: '8px', color: '#1e293b' }}>
              <Building2 size={18} color="#0284c7" />
              Stay & Price-Gouging Radar
            </h3>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
              {hotels.map((h, i) => (
                <motion.div
                  key={i}
                  whileHover={{ scale: 1.02 }}
                  style={{ background: '#f8fafc', border: '1px solid #e2e8f0', borderRadius: '10px', padding: '14px' }}
                >
                  <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                    <div>
                      <strong style={{ color: '#334155' }}>{h.name}</strong>
                      <div style={{ fontSize: '12px', color: '#64748b' }}>{h.category}</div>
                    </div>
                    <div style={{ textAlign: 'right' }}>
                      <div style={{ fontWeight: 'bold', fontSize: '16px', color: h.surge ? '#dc2626' : '#16a34a' }}>
                        ₹{h.price}
                      </div>
                      {h.surge && (
                        <span style={{ fontSize: '10px', background: '#fee2e2', color: '#dc2626', padding: '2px 6px', borderRadius: '4px', fontWeight: 'bold' }}>
                          Surge Alert
                        </span>
                      )}
                    </div>
                  </div>
                  <div style={{ marginTop: '8px', fontSize: '12px', display: 'flex', justifyContent: 'space-between', color: '#475569' }}>
                    <span>Rooms Left: <strong>{h.rooms}</strong></span>
                    <span style={{ color: h.category.includes('Dharamshala') ? '#16a34a' : '#64748b', display: 'flex', alignItems: 'center', gap: '4px' }}>
                      <ShieldCheck size={14} /> Fair Price Verified
                    </span>
                  </div>
                </motion.div>
              ))}
            </div>
          </div>

        </div>

      </div>
    </div>
  );
}
